insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-06', 'l-nahw', 2, 'ما الجملة الصحيحة نحوياً؟', '["الطالبان لم يحضرا الدرس","الطالبان لم يحضران الدرس","الطالبان لم يحضروا الدرس","الطالبان لم يحضرون الدرس"]'::jsonb, 0, '«لم» تجزم الفعل، والأفعال الخمسة تجزم بحذف النون: لم يحضرا. والفاعل مثنى فتلزم ألف الاثنين.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-07', 'l-nahw', 3, '«صلّيتُ في مساجدَ عدةٍ». جُرّت كلمة «مساجد» بالفتحة لأنها:', '["مضاف إليه","ممنوعة من الصرف (صيغة منتهى الجموع)","جمع مؤنث سالم","اسم مقصور"]'::jsonb, 1, '«مساجد» على صيغة منتهى الجموع فهي ممنوعة من الصرف، تجر بالفتحة نيابة عن الكسرة ما لم تُعرَّف بأل أو تُضف.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
