insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-10', 'l-nahw', 3, 'ما الصواب في قولنا؟', '["حضر أحدَ عشرَ طالباً","حضر أحدُ عشرَ طالباً","حضر إحدى عشر طالباً","حضر أحد عشرة طالباً"]'::jsonb, 1, 'العدد 11 مبني على فتح الجزأين في محل رفع فاعل (أحدَ عشرَ)، لكن الأفصح المتداول في الاختبارات: «أحدَ عشرَ» بفتح الجزأين، والفاعل محلاً مرفوع، والمعدود مفرد منصوب. الخيار (ب) يضبط الجزء الأول بالضم وهو خطأ شائع، والصحيح الخيار الأول.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
